std::optional<unsigned> ScriptSession::destructableWeapon(const UnitState& source,const DestructableState& target){
    if(source.ethereal() || source.morphed() || source.spinning() || target.removed || !target.visible || target.invulnerable || target.life<=0)return {};std::set<std::string> types;std::stringstream stream(target.targetTypes);std::string part;while(std::getline(stream,part,',')){auto first=part.find_first_not_of(" \t");if(first!=std::string::npos)types.insert(part.substr(first,part.find_last_not_of(" \t")-first+1));}for(unsigned slot=0;slot<2;++slot){if(!weaponEnabled(source,slot))continue;auto weapon=unitWeapon(source,slot);if(source.attackPrevented(weapon.kind!="normal"))continue;for(auto& type:types)if(weapon.targets.contains(type))return slot;}return {};
}
bool ScriptSession::attackDestructable(std::uint32_t source,std::uint32_t target){
    if(!alive(source,NativeKind::Unit) || !alive(target,NativeKind::Destructable))return false;auto unit=units_.at(source);auto d=destructables_.at(target);if(unit->paused || unit->stunned() || unit->construction || unit->unsummon || unit->hidden() || unit->removing || number(unit->life)<=0 || fog(unit->owner).state(d->position)!=4)return false;auto slot=destructableWeapon(*unit,*d);if(!slot)return false;auto weapon=unitWeapon(*unit,*slot);float range=weapon.range+unit->collision+d->radius;float distance=std::hypot(number(d->position.x)-number(unit->x),number(d->position.y)-number(unit->y));if(distance<=range && distance>=weapon.minimumRange){unit->route.clear();unit->waypoint=0;}else if(unit->stationaryBuilding() || !chase(*unit,d->position,std::max(0.f,range-8)))return false;if(!cancelCombat(*unit) || !alive(target,NativeKind::Destructable) || !destructableWeapon(*unit,*d))return false;unit->combat.widgetTarget=target;unit->combat.widgetTargetRevision=d->lifeRevision;unit->combat.repath=simulationTime_+.25;unit->currentOrder=851983;unit->holding=false;ScriptContext context;context.issuedOrder=851983;context.orderTarget=target;unitEvent(source,40,77,context);return true;
}
void ScriptSession::combatDestructable(std::uint32_t id,double delta){
    if(!alive(id,NativeKind::Unit))return;auto unit=units_.at(id);auto& order=unit->combat;auto targetId=order.widgetTarget;auto clear=[&]{order.widgetTarget=0;order.windup.reset();++order.revision;unit->route.clear();unit->waypoint=0;unit->currentOrder=0;};if(!alive(targetId,NativeKind::Destructable)){clear();return;}auto d=destructables_.at(targetId);if(d->lifeRevision!=order.widgetTargetRevision){clear();return;}auto slot=destructableWeapon(*unit,*d);if(!slot || fog(unit->owner).state(d->position)!=4){clear();return;}auto weapon=unitWeapon(*unit,*slot);float distance=std::hypot(number(d->position.x)-number(unit->x),number(d->position.y)-number(unit->y)),range=weapon.range+unit->collision+d->radius;if(order.windup){if(simulationTime_>=order.windup->due){auto windup=*order.windup;order.windup.reset();if(windup.revision==order.revision && distance<=range+weapon.rangeBuffer)launchDestructableAttack(id,targetId,windup.weapon);}return;}if(distance>range || distance<weapon.minimumRange){if(!unit->holding && !unit->stationaryBuilding() && simulationTime_>=order.repath){if(distance<weapon.minimumRange && distance>.001f){float radius=weapon.minimumRange+unit->collision+d->radius+16;WorldPoint point{real(number(d->position.x)+(number(unit->x)-number(d->position.x))/distance*radius),real(number(d->position.y)+(number(unit->y)-number(d->position.y))/distance*radius)};chase(*unit,point,0);}else chase(*unit,d->position,std::max(0.f,range-8));order.repath=simulationTime_+.25;}return;}unit->route.clear();unit->waypoint=0;if(!unit->stationaryBuilding()){float heading=std::fmod(std::atan2(number(d->position.y)-number(unit->y),number(d->position.x)-number(unit->x))*180.f/3.14159265359f+360.f,360.f);if(turnUnit(*unit,heading,delta)>.2f)return;}if(simulationTime_<order.nextAttack)return;float speed=1+unit->technology.attackSpeed+unit->equipment.attackSpeed+unit->aura.attackSpeed+unit->spellBonus(&UnitBuff::attackBonus)-unit->spellAttackReduction();if(unit->hero && (!unit->illusion || gameplayNumber("IllusionsGetAttackSpeedBonus",1)!=0))speed+=unit->appliedHeroStats[1]*gameplayNumber("AgiAttackSpeedBonus",.02f);speed=std::clamp(speed,.2f,5.f);order.animationSpeed=speed;order.nextAttack=simulationTime_+std::max(1./32,double(weapon.cooldown/speed));order.animationEnd=simulationTime_+(weapon.point+weapon.backswing)/speed;order.windup=AttackWindup{targetId,*slot,simulationTime_+weapon.point/speed,order.revision};unit->animation="Attack";unit->animationIndex.reset();unit->animationQueue.clear();unit->animationTime=0;++unit->animationGeneration;
}
void ScriptSession::launchDestructableAttack(std::uint32_t source,std::uint32_t target,unsigned slot){
    if(!alive(source,NativeKind::Unit) || !alive(target,NativeKind::Destructable))return;auto unit=units_.at(source);auto d=destructables_.at(target);auto selected=destructableWeapon(*unit,*d);if(!selected || *selected!=slot || fog(unit->owner).state(d->position)!=4)return;auto weapon=unitWeapon(*unit,slot);float damage=weapon.base;auto sides=std::max(1u,weapon.sides);for(unsigned i=0;i<weapon.dice;++i)damage+=float(random()%sides+1);if(unit->hero){auto primary=definitions().field(unit->type,"UnitBalance","Primary");unsigned attribute=primary=="STR"?0:primary=="AGI"?1:2;damage+=unit->appliedHeroStats[attribute];}CombatProjectile shot;shot.definition=weapon;shot.source=source;shot.target=target;shot.sourceType=unit->type;shot.owner=unit->owner;shot.weapon=slot;shot.damage=attackDamageBeforeProc(*unit,weapon,damage);shot.destructableTarget=true;shot.targetLifeRevision=d->lifeRevision;float angle=number(unit->facing)*3.14159265359f/180;shot.start={real(number(unit->x)+std::cos(angle)*weapon.launchX-std::sin(angle)*weapon.launchY),real(number(unit->y)+std::sin(angle)*weapon.launchX+std::cos(angle)*weapon.launchY)};shot.position=shot.start;shot.endpoint=d->position;shot.startMovement=pathMovement(unit->movementType);shot.endMovement=PathMovement::Ground;shot.startHeight=unit->displayFlyHeight()+weapon.launchZ;shot.endHeight=60;shot.distance=std::hypot(number(shot.start.x)-number(shot.endpoint.x),number(shot.start.y)-number(shot.endpoint.y));shot.born=simulationTime_;if(weapon.kind=="normal" || weapon.kind=="instant"){impact(shot);return;}if(weapon.speed<=0)throw std::runtime_error("Projectile weapon requires source missile speed: "+ObjectData::name(unit->type));if(projectiles_.size()>=8192)throw std::runtime_error("Live projectile budget exceeded");shot.id=++projectileId_;projectiles_.emplace(shot.id,std::move(shot));
}
